sys_script.script:
(function executeRule(current, previous) {
  if (!current.scholarship_program || current.scholarship_program.nil()) {
    gs.addErrorMessage('Scholarship Program reference is required.');
    current.setAbortAction(true);
    return;
  }
  if (!current.student || current.student.nil()) {
    gs.addErrorMessage('Student reference is required.');
    current.setAbortAction(true);
    return;
  }
  var prog = current.scholarship_program.getRefRecord();
  if (!prog.isValidRecord()) {
    gs.addErrorMessage('Selected Scholarship Program is invalid.');
    current.setAbortAction(true);
    return;
  }
  var progStatus = (prog.program_status + '').toLowerCase();
  if (progStatus !== 'active') {
    gs.addErrorMessage('Selected Scholarship Program is currently not active.');
    current.setAbortAction(true);
    return;
  }
  // Deadline Check
  if (prog.end_date && !prog.end_date.nil()) {
    var endDt = new GlideDateTime(prog.end_date.getDisplayValue());
    var nowDt = new GlideDateTime();
    if (endDt.getNumericValue() < nowDt.getNumericValue()) {
      gs.addErrorMessage('Application deadline for this scholarship program has passed (' + prog.end_date + ').');
      current.setAbortAction(true);
      return;
    }
  }
  // Available Seats Check
  var seats = parseInt(prog.available_seats, 10);
  if (isNaN(seats) || seats <= 0) {
    gs.addErrorMessage('No available seats remaining for this scholarship program.');
    current.setAbortAction(true);
    return;
  }
  // Get student record for fallback / sync
  var stu = current.student.getRefRecord();
  var acadPerc = parseFloat(current.academic_percentage);
  if (isNaN(acadPerc) || acadPerc === 0) {
    acadPerc = parseFloat(stu.cgpa) || 0;
    if (acadPerc > 0) {
      current.academic_percentage = acadPerc;
    }
  }
  var famInc = parseFloat(current.annual_family_income);
  if (isNaN(famInc) || famInc === 0) {
    famInc = parseFloat(stu.annual_family_income) || 0;
    if (famInc > 0) {
      current.annual_family_income = famInc;
    }
  }
  // Eligibility Check
  var minPerc = parseFloat(prog.minimum_percentage) || 0;
  if (minPerc > 0 && acadPerc < minPerc) {
    gs.addErrorMessage('Student academic percentage (' + acadPerc + '%) does not meet minimum eligibility criteria of ' + minPerc + '%.');
    current.setAbortAction(true);
    return;
  }
  var maxInc = parseFloat(prog.maximum_family_income) || 0;
  if (maxInc > 0 && famInc > maxInc) {
    gs.addErrorMessage('Annual family income (₹' + famInc + ') exceeds maximum limit of ₹' + maxInc + ' for this scholarship program.');
    current.setAbortAction(true);
    return;
  }
})(current, previous);
